#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_is_populated() {
        let actions = popular_actions();
        assert!(!actions.is_empty());
        assert!(
            actions.len() >= 200,
            "expected a large table, got {}",
            actions.len()
        );
    }

    #[test]
    fn known_action_present() {
        let actions = popular_actions();
        let md = actions
            .get("8398a7/action-slack@v3")
            .expect("action-slack@v3 should be a known popular action");
        assert_eq!(md.name, "action-slack");
        assert!(md.inputs.contains_key("author_name"));
        // `status` is a required input.
        assert!(md.inputs["status"].required);
        assert!(!md.inputs["channel"].required);
    }

    #[test]
    fn outdated_spec_present() {
        let outdated = outdated_popular_action_specs();
        assert!(!outdated.is_empty());
        assert!(
            outdated.contains("actions/checkout@v2"),
            "actions/checkout@v2 should be an outdated spec"
        );
    }

    #[test]
    fn deprecated_input_message_ported() {
        // Deprecated inputs carry a non-empty deprecation message.
        let actions = popular_actions();
        let deprecated: Vec<_> = actions
            .values()
            .flat_map(|md| md.inputs.values())
            .filter(|i| i.deprecated)
            .collect();
        assert!(!deprecated.is_empty(), "expected some deprecated inputs");
        assert!(deprecated.iter().all(|i| !i.deprecation_message.is_empty()));
    }
}
